/// <summary>
/// Adds standard item lookup fields: ItemId, NameAlias, ProductName, Item group, Item Type.
/// </summary>
protected void addStandardFields()
{

    next addStandardFields();

    this.avaAddLookupField(fieldNum(InventItemIdLookupSimpleView, NDXModelNumber));
    this.avaAddLookupField(fieldNum(InventItemIdLookupSimpleView, KCS_KAOItemState));
    this.avaAddLookupField(fieldNum(InventItemIdLookupSimpleView, AVANetWeight));
}

/// <summary>
/// Replacement method to add lookupFields
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void avaAddLookupField(FieldId _fieldId)
{
    lookupFields.addEnd(_fieldId);
}
